B.bnt=new A.t6("none","It cannot be judged: the wire functions were not verified.",!1,!1,!1)
B.bnu=new A.t6("smoke","The loose connection overheats: it glows, smokes and chars the device. In a real wall this can start a fire.",!1,!1,!0)
B.bnv=new A.t6("none","It does not work as it should: some part runs wrongly or not at all. That does not tell you what is wrong, so check against the diagram.",!1,!1,!1)
B.bnw=new A.t6("none","It runs. There is nothing to see, and that is the danger: with no ground, a fault would energize the metal parts.",!0,!1,!1)
