B.bny=new A.t6("none","It works, and every safety rule is met.",!0,!1,!1)
B.bnz=new A.t6("none","Nothing happens: it is dead. But the hot wire is connected, so it can still be live. No sparks, no smoke: that does not make it safe.",!1,!1,!1)
