B.bUR=new A.jC("Voltage tester","A pen that glows or beeps near live wires. Test it on a known live outlet first, so you know it works.")
B.bUX=new A.jC("Wire strippers","Strip the plastic off without nicking the copper. A nick weakens the wire.")
B.bV2=new A.jC("Adjustable wrench","For nuts on valves and hoses. Hold the fitting steady with a second wrench so you do not twist the pipe.")
B.bUV=new A.jC("Drill and screw gun","A drill makes holes through studs. A screw gun sets drywall screws to the right depth.")
B.bUP=new A.jC("Level and tape measure","Measure twice, cut once. A level makes sure outlets, shelves and pipes are straight.")
